const body = $input.first().json.body || $input.first().json;
const whatsapp_numero = String(body.whatsapp_numero || '').trim();
const digits = whatsapp_numero.replace(/\D/g, '');

let erro = '';
if (digits.length < 12 || digits.length > 13) erro = 'Numero de WhatsApp invalido.';

const codigo = String(Math.floor(100000 + Math.random() * 900000));
const expira_em = new Date(Date.now() + 5 * 60 * 1000).toISOString();

return [{ json: { valido: !erro, erro, whatsapp_numero, digits, codigo, expira_em } }];

const dados = $('Preparar Codigo Login').first().json;
return [{ json: {
  numero: dados.digits,
  texto: 'Seu codigo de acesso ao Licitacoes IA: ' + dados.codigo + '\n\nVale por 5 minutos. Se voce nao pediu esse codigo, ignore esta mensagem.'
} }];

