const rows = $input.all();
const row = rows.length ? rows[0].json : null;
let valido = true, erro = '';
if (!row) { valido = false; erro = 'Codigo invalido.'; }
else if (row.usado) { valido = false; erro = 'Esse codigo ja foi usado. Peca um novo.'; }
else if (new Date(row.expira_em).getTime() < Date.now()) { valido = false; erro = 'Codigo expirado. Peca um novo.'; }
return [{ json: { valido, erro, codigo_id: row ? row.id : null } }];

