## Listar Perfis de Busca
Rota: POST /webhook/licitacoes/perfis-listar
Body: { token }

parameters.jsCode:
const rows = $input.all();
const row = rows.length ? rows[0].json : null;
const valido = !!(row && new Date(row.expira_em).getTime() > Date.now());
return [{ json: { valido, usuario_id: row ? row.usuario_id : null } }];

const body = $input.first().json.body || $input.first().json;
const nome_perfil = String(body.nome_perfil || '').trim();
const objeto_palavras_chave = Array.isArray(body.objeto_palavras_chave) ? body.objeto_palavras_chave.map(String).filter(Boolean) : [];
const modalidadesPermitidas = ['pregao_eletronico', 'dispensa'];
const modalidades = Array.isArray(body.modalidades) ? body.modalidades.filter(m => modalidadesPermitidas.includes(m)) : [];
const valor_min = body.valor_min !== null && body.valor_min !== undefined && body.valor_min !== '' ? Number(body.valor_min) : null;
const valor_max = body.valor_max !== null && body.valor_max !== undefined && body.valor_max !== '' ? Number(body.valor_max) : null;
const uf = Array.isArray(body.uf) ? body.uf.map(String) : [];
const municipio = Array.isArray(body.municipio) ? body.municipio.map(String) : [];
const perfil_id = body.perfil_id || null;
const token = String(body.token || '');

let erro = '';
if (!nome_perfil) erro = 'De um nome pro alerta.';
else if (!objeto_palavras_chave.length) erro = 'Adicione pelo menos uma palavra-chave.';
else if (!modalidades.length) erro = 'Marque pelo menos um tipo de licitacao.';
else if (valor_min !== null && valor_max !== null && valor_min > valor_max) erro = 'O valor minimo nao pode ser maior que o maximo.';

return [{ json: { valido: !erro, erro, token, perfil_id, tem_perfil_id: !!perfil_id, nome_perfil, objeto_palavras_chave, modalidades, valor_min, valor_max, uf, municipio } }];

